"""Typed CB28 result words and verified rule-bridge/counter/action listings."""
import sys,json
from pathlib import Path
sys.dont_write_bytecode=True
p=Path(__file__).resolve().parents[2];sys.path.insert(0,str(p/'skoolkit-10.1'))
from skoolkit.traceutils import disassemble
from skoolkit.z80 import Assembler
m=bytes(0x5d80)+(p/'sherlock-analisi/block-10.bin').read_bytes();asm=Assembler()
regions=[(0xcb28,0xcb2c,'data','Risultati persistenti: conservati anche attraverso rifiuti senza callback'),(0xcb2c,0xcb41,'code','Ponte: il predicato falso salva i registri, il corpo ricarica i risultati'),(0xc9bf,0xca76,'code','Confine tra preflight, predicato e corpo immediato o differito'),(0xd206,0xd21c,'code','Iteratore delle uscite: avanza di tre byte e lascia il terminatore'),(0xd33c,0xd349,'code','Stanza dell’attore dal descrittore A017'),(0xd46c,0xd495,'code','Ricerca prima uscita per cancello o destinazione: conserva IY'),(0xdd61,0xdd65,'data','Intestazione location.exitDirection: classi e predicato'),(0xdd65,0xdd84,'code','Direzione dalla prima uscita: ritorno del record anche su fallimento'),(0xc4e8,0xc571,'code','Preflight delle azioni: rifiuti senza entrare nel ponte')]
notes={0xcb28:'Word persistenti IX/IY dell’ultima chiamata CB34. Un tentativo rifiutato prima di CB34 non le cancella. OldSAVE senza valore restaunknown.',0xcb2c:'Solo il corpo immediato ricarica i risultati precedenti. Non sono genericamente i due argomenti correnti.',0xcb34:'Predicato o corpo chiamato con IX/IY scelti dal chiamante. Il predicato falso NON evita i due store successivi.',0xcb37:'Writer IX: nella ricerca DD6E è l’indirizzo del primo record uscita trovato, oppure quello del terminatoreFF.',0xcb3b:'Writer IY: D471 ripristina l’IY entrante; nel predicato DD6E è l’intestazioneDD61.',0xc9dd:'Nessun predicato senza bit6. I rifiuti dei vincoli prima di questo punto non producono risultati nuovi.',0xc9eb:'La chiamata predicato passaCB34 anche se ritornerà falso. Non condizionare la pubblicazione a successo.',0xca40:'Bit7: il corpo viene differito, senza CB2C. L’eventuale risultato del predicato rimane.',0xca64:'Corpo immediato viaCB2C; DD65 conserva entrambi i puntatori e legge la direzione dal record selezionato.',0xd206:'Iteratore a passi3. Il chiamante parte da room.start+6: prima iterazione torna room.start+9.',0xd215:'Il primo byte è direzione, oppureFF. Anche in caso di terminazione IX rimane sul recordFF.',0xd33d:'Seleziona il descrittore dell’attore corrente, non quello del destinatario dell’uscita.',0xd344:'D224 risale i contenitori e restituisce il record stanza; non supporre che la stanza sia sempre direttamente sull’attore.',0xd46c:'Ingresso per cancello: offset1. DD6E usa inveceD471, offset2 destinazione.',0xd471:'Ingresso usato daDD6E: cerca la prima uscita la cui destinazione coincide conA034.',0xd474:'Selezione del campo tramite l’operando mutabileD48D; non è un nuovo record dati.',0xd479:'Salva IY prima dell’iteratore che lo modifica.',0xd480:'Sei byte prima della prima uscita; D206 aggiunge3 prima di leggere.',0xd486:'Il primo record corrispondente vince. Non saltare quello con direzione11 o12 per cercarne uno successivo valido.',0xd491:'Ripristina IY anche se la lista termina senza corrispondenza.',0xdd61:'Quattro byte di intestazione, non istruzioni. IY=DD61 al predicato indipendentemente dai risultati entranti.',0xdd65:'Corpo: scrive il byte direzione nel secondo argomento di lavoro; non cambia IX/IY.',0xdd6e:'A034 contiene la destinazione cercata; D471 cerca nella stanza dell’attore.',0xdd76:'Nessuna uscita: fallimentoDC15, IX resta sul terminatore e viene comunque pubblicato daCB37.',0xdd7e:'Direzione>=11: fallimento sul PRIMO record trovato. Non filtrare prima la lista per direzioni valide.',0xdd81:'Accetta i valori inferiori11, compreso0. OR1 produce successo senza modificare il record.',0xc4e9:'A00B=0: preparazione, non esecuzione del callback.',0xc524:'Ricerca argomenti esaurita: ritorno prima diCB34, nessuna cancellazione dei risultati.',0xc539:'Altro ritorno preflight senza writer. Il modello conserva le word soltanto quando il rifiuto è dimostrato anteriore al ponte.',0xc53f:'La selezione concreta prosegueC929. Questo dossier non completa i risultati di tutti i suoi callback.'}
fields=[['CB28–CB29','Risultato IX','Primo record uscita oppure terminatore; persiste nei rifiuti senza callback'],['CB2A–CB2B','Risultato IY','DD61 nel predicato; preservato dal bodyDD65'],['Writer','CB37/CB3B','Anche dopo predicato falso; mai per il solo preflight'],['LOAD','Proprietà esplicita','Assente restaunknown fino a writer ricostruito']]
lines=['; Analisi offline: dati tipizzati separati dal codice; byte riasssemblati contro il payload.'];count=total=0
for a,b,kind,label in regions:
 lines+=['',f'    ORG ${a:04X}',f'; {kind.upper()}: {label}'];at=a
 while at<b:
  if kind=='data':n=min(8,b-at);op='DEFB '+','.join(f'${v:02X}'for v in m[at:at+n])
  else:op,n=disassemble(m,at);count+=1
  assert at+n<=b,(hex(at),op);assert bytes(asm.assemble(op,at))==m[at:at+n]
  lines.append(f'    {op:<37} ; ${at:04X} {m[at:at+n].hex(" ")}'+(' | '+notes[at]if at in notes else''));at+=n;total+=n
root=p/'sherlock-js/results/rule-result-lifetime';(root/'rule-result-lifetime.asm').write_text('\n'.join(lines)+'\n');(root/'listing-verification.json').write_text(json.dumps(dict(roundtrip_equal=True,instructions=count,bytes_roundtripped=total,regions=[dict(start=f'{a:04X}',end_exclusive=f'{b:04X}',kind=k,label=l,atlas_priority=156,**({'fields':fields}if a==0xcb28 else{}))for a,b,k,l in regions]),indent=2,ensure_ascii=False)+'\n');print(count,total)
